/* ═══════════════════════════════════════
   SUPABASE DATA LAYER  (sync-on-save)
   ───────────────────────────────────────
   The whole app keeps using one in-memory `DB` object exactly as
   before. This layer (a) loads shared data from Supabase into `DB`
   on login, and (b) pushes changes back in the background whenever
   saveDB() runs. If Supabase isn't configured, everything falls
   back to localStorage-only mode automatically.
═══════════════════════════════════════ */
const SB = { client:null, enabled:false, bucket:'claimdesk-scans', ready:false };

async function initSupabase(){
  try{
    // Wait for config to be loaded from API (with timeout)
    const waitForConfig = new Promise((resolve) => {
      if (window.CONFIG_READY) {
        resolve();
      } else {
        const timeout = setTimeout(() => {
          console.warn('Config loading timeout - proceeding with offline mode');
          resolve();
        }, 3000);
        
        window.addEventListener('configReady', () => {
          clearTimeout(timeout);
          resolve();
        }, { once: true });
      }
    });
    
    await waitForConfig;
    
    const cfg = (window.CLAIMDESK_CONFIG)||{};
    if(cfg.SUPABASE_URL && cfg.SUPABASE_ANON_KEY && window.supabase){
      SB.client  = window.supabase.createClient(cfg.SUPABASE_URL, cfg.SUPABASE_ANON_KEY);
      SB.bucket  = cfg.SCANS_BUCKET || 'claimdesk-scans';
      SB.enabled = true;
      console.log('ClaimDesk: Supabase connected.');
    }else{
      console.warn('ClaimDesk: Supabase not configured — running in offline localStorage mode.');
    }
  }catch(e){
    console.error('ClaimDesk: Supabase init failed, using offline mode.', e);
    SB.enabled = false;
  }
}

// Run initSupabase immediately, and keep a reference to it so other code
// (like doLogin) can wait for it to finish before checking SB.enabled.
const SB_INIT_PROMISE = initSupabase();

/* Pull all shared data from Supabase into the in-memory DB (called on login). */
/* Fills in any missing pieces of a job object with safe empty defaults, matching
   what newJob() creates. Used whenever a job is loaded or updated from the server,
   in case its stored data is incomplete for any reason — prevents render crashes. */
/* CRITICAL FIX: never let a job update coming from the server silently erase
   VO1/VO2 pricing or the type field that we already have locally. This is
   what caused claim documents (and the Job Summary panel) to show P0.00 /
   "Type: undefined" right after Finance generated claim docs — a delayed or
   partial sync of the job row was overwriting the real, priced job in memory. */
function preserveVOData(existing, incoming){
  if(!existing) return;
  
  // CRITICAL FIX: If incoming update is older than or equal to the last local edit,
  // do not overwrite vo1, vo2, or type fields. This prevents stale Supabase echoes
  // (with incomplete data) from silently erasing VO pricing after generateClaimDocs().
  const lastLocalEdit = _localEditAt[incoming.wo];
  if(lastLocalEdit && incoming._updatedAt){
    const incomingTime = new Date(incoming._updatedAt).getTime();
    if(incomingTime <= lastLocalEdit){
      // This is an older or equal-aged update — do not overwrite critical fields
      return;
    }
  }
  
  const incomingHasVO1 = incoming.vo1 && incoming.vo1.items && incoming.vo1.items.length>0;
  const existingHasVO1 = existing.vo1 && existing.vo1.items && existing.vo1.items.length>0;
  if(!incomingHasVO1 && existingHasVO1) incoming.vo1 = existing.vo1;

  const incomingHasVO2 = incoming.vo2 && incoming.vo2.items && incoming.vo2.items.length>0;
  const existingHasVO2 = existing.vo2 && existing.vo2.items && existing.vo2.items.length>0;
  if(!incomingHasVO2 && existingHasVO2) incoming.vo2 = existing.vo2;

  if((incoming.type===undefined || incoming.type===null) && existing.type!==undefined) incoming.type = existing.type;
}

function hydrateJob(j){
  if(!j.vo1) j.vo1={items:[], lf:29.25, mk:0};
  if(!j.vo2) j.vo2={items:[], lf:29.25, mk:10};
  if(!j.actions) j.actions={};
  if(!j.fieldData) j.fieldData={};
  if(!j.gisData) j.gisData={};
  if(!j.scans) j.scans={};
  if(!j.savedDocs) j.savedDocs={};
  if(!j.gisDocs) j.gisDocs=[];
  if(!j.gisCerts) j.gisCerts=[];
  if(j.vo1 && (j.vo1.lf === null || j.vo1.lf === undefined)) j.vo1.lf = 29.25;
  if(j.vo1 && (j.vo1.mk === null || j.vo1.mk === undefined)) j.vo1.mk = 0;
  if(j.vo2 && (j.vo2.lf === null || j.vo2.lf === undefined)) j.vo2.lf = 29.25;
  if(j.vo2 && (j.vo2.mk === null || j.vo2.mk === undefined)) j.vo2.mk = 10;
  return j;
}

async function syncFromSupabase(){
  if(!SB.enabled){ SB.ready = true; return; }
  try{
    const c = SB.client;
    const [jobsR, docsR, batchR, logR, notifR, metaR] = await Promise.all([
      c.from('jobs').select('*'),
      c.from('documents').select('*'),
      c.from('claim_batches').select('*'),
      c.from('activity_log').select('*').order('ts',{ascending:false}).limit(500),
      c.from('notifications').select('*').order('ts',{ascending:false}).limit(300),
      c.from('app_meta').select('*'),
    ]);

    const jobs = {};
    (jobsR.data||[]).forEach(row=>{
      const j = row.data && typeof row.data==='object' ? row.data : {};
      j.wo = row.wo; j.cust = row.cust; j.loc = row.loc;
      j.phase = row.phase; j.stage = row.stage; j.claimRef = row.claim_ref||j.claimRef||'';
      j._updatedAt = row.updated_at;
      preserveVOData(DB.jobs[row.wo], j);
      hydrateJob(j);
      jobs[row.wo] = j;
    });
    console.log('syncFromSupabase: fetched', Object.keys(jobs).length, 'jobs from Supabase:', jobs);
    DB.jobs = jobs;

    (docsR.data||[]).forEach(d=>{
      const j = DB.jobs[d.wo]; if(!j) return;
      if(d.is_signed){
        j.scans = j.scans||{};
        j.scans[d.doc_type] = {
          storagePath:d.storage_path, filename:d.filename,
          uploadedAt:d.created_at, role:d.uploaded_role,
          url: SB.client.storage.from(SB.bucket).getPublicUrl(d.storage_path).data.publicUrl,
        };
      }else if(d.html){
        j.savedDocs = j.savedDocs||{};
        j.savedDocs[d.doc_type] = { html:d.html, savedAt:d.created_at, role:d.uploaded_role };
      }
    });

    const notifs = {admin:[],finance:[],md:[]};
    (notifR.data||[]).forEach(n=>{
      (notifs[n.role] = notifs[n.role]||[]).push({ id:n.id, msg:n.msg, wo:n.wo, read:n.is_read, ts:n.ts });
    });
    DB.notifs = notifs;

    DB.actLog = (logR.data||[]).map(l=>({ wo:l.wo, action:l.action, role:l.role, ts:l.ts }));

    DB.batchDocs = {};
    (batchR.data||[]).forEach(b=>{
      DB.batchDocs[b.id] = { cert:b.cert_no, wos:b.wos||[], docs:b.docs||{}, scans:b.scans||{}, createdAt:b.created_at };
    });

    const seq = (metaR.data||[]).find(m=>m.key==='certSeq');
    if(seq && seq.value!=null) DB.certSeq = Number(seq.value)||DB.certSeq;

    SB.ready = true;
  }catch(e){
    console.error('ClaimDesk: load from Supabase failed.', e);
    SB.ready = true;
    if(typeof toast==='function') toast('Could not reach the server — showing last saved data','am');
  }
}

/* Push current DB state to Supabase (debounced; called by saveDB). */
const _dirtyJobs = new Set();
// CRITICAL FIX: remember the timestamp of the last LOCAL edit per work order.
// This lets us reject a delayed realtime echo of an OLDER save even after
// _dirtyJobs has already been cleared by a newer save — which is what was
// causing uploaded documents / VO1 rows to appear to "disappear" until the
// page was refreshed.
const _localEditAt = {};
function markJobDirty(wo){ _dirtyJobs.add(wo); _localEditAt[wo] = Date.now(); }
let _sbSaveTimer = null;

/* Only one push to Supabase is ever allowed to run at a time. If a save is
   requested while one is already in flight, it waits for that one to finish
   and then runs again automatically — so it always ends up sending the latest
   data, and two actions happening close together can never overwrite each
   other's changes. */
let _pushInFlight = null;
function _runPushQueued(){
  const run = _pushInFlight ? _pushInFlight.then(()=>_pushNow(), ()=>_pushNow()) : _pushNow();
  _pushInFlight = run.finally(()=>{ if(_pushInFlight===run) _pushInFlight=null; });
  return _pushInFlight;
}

function pushToSupabase(){
  if(!SB.enabled) return;
  clearTimeout(_sbSaveTimer);
  _sbSaveTimer = setTimeout(_runPushQueued, 400);
}
/* Forces any pending debounced save to run right now, and waits for it to finish.
   Call this before anything that's about to clear or replace DB (like logging out). */
async function flushPendingSave(){
  if(_sbSaveTimer){
    clearTimeout(_sbSaveTimer);
    _sbSaveTimer = null;
    await _runPushQueued();
  }else if(_pushInFlight){
    await _pushInFlight;
  }
}
async function saveDBAndWait(){
  const ov=document.getElementById('loadOverlay');
  if(ov) ov.style.display='flex';
  try{
    clearTimeout(_sbSaveTimer);
    _sbSaveTimer=null;
    await _runPushQueued();
    // CRITICAL: Wait a moment for Supabase to process
    await new Promise(resolve=>setTimeout(resolve,300));
    // Validate that data was actually saved (basic check)
    // This prevents showing zero amounts before database confirms data
  }catch(e){
    console.error('Save failed:',e);
    toast('⚠️ Could not save to the server — check your connection and try again','am');
    throw e;
  }finally{
    if(ov) ov.style.display='none';
  }
}

async function _pushNow(){
  if(!SB.enabled) return;
  const c = SB.client;
  try{
    const wosToPush = _dirtyJobs.size ? [..._dirtyJobs] : Object.keys(DB.jobs||{});
    const jobRows = wosToPush.filter(wo=>DB.jobs[wo]).map(wo=>{
      const j = DB.jobs[wo];
      return { wo:j.wo, cust:j.cust, loc:j.loc, phase:j.phase, stage:j.stage, claim_ref:j.claimRef||null, data:j };
    });
    if(jobRows.length){
      const {error:jobsErr} = await c.from('jobs').upsert(jobRows, {onConflict:'wo'});
      if(jobsErr) throw jobsErr;
    }
    _dirtyJobs.clear();

    const notifRows=[];
    Object.entries(DB.notifs||{}).forEach(([role,list])=>{
      (list||[]).forEach(n=> notifRows.push({ id:String(n.id), role, msg:n.msg, wo:n.wo||null, is_read:!!n.read, ts:n.ts }));
    });
    if(notifRows.length) await c.from('notifications').upsert(notifRows, {onConflict:'id'});

    const batchRows = Object.entries(DB.batchDocs||{}).map(([id,b])=>({
      id, cert_no:b.cert, wos:b.wos||[], docs:b.docs||{}, scans:b.scans||{},
    }));
    if(batchRows.length) await c.from('claim_batches').upsert(batchRows, {onConflict:'id'});

    if(DB.certSeq!=null) await c.from('app_meta').upsert({key:'certSeq', value:DB.certSeq}, {onConflict:'key'});
  }catch(e){
    console.error('ClaimDesk: background save to Supabase failed.', e);
    if(typeof toast==='function') toast('⚠️ Your last change was NOT saved to the server — check permissions/connection and try again','rd');
  }
}

/* Append a single activity-log row to Supabase. */
async function pushLogRow(entry){
  if(!SB.enabled) return;
  try{ await SB.client.from('activity_log').insert({ wo:entry.wo||null, action:entry.action, role:entry.role, ts:entry.ts }); }
  catch(e){ /* non-fatal */ }
}

let _rtChannel = null;
function subscribeRealtime(){
  if(!SB.enabled || _rtChannel) return;
  _rtChannel = SB.client.channel('claimdesk-live')
    .on('postgres_changes', {event:'*', schema:'public', table:'jobs'}, payload=>{
      const row = payload.new || payload.old;
      if(!row) return;
      if(payload.eventType==='DELETE'){ delete DB.jobs[row.wo]; refreshAll(); return; }
      // Don't let a realtime message overwrite a job that still has local
      // changes we haven't finished pushing yet — otherwise an in-flight
      // upload (or any other unsaved edit) gets clobbered by an older
      // echo of a previous save, and the UI appears to "forget" it.
      if(_dirtyJobs.has(row.wo)) return;
      // CRITICAL FIX: also reject any echo that is older than the last LOCAL
      // edit for this job, even after _dirtyJobs has already been cleared.
      // Without this, a delayed confirmation of an EARLIER save can arrive
      // after a LATER save was already made locally and silently overwrite
      // the newer in-memory data with the older snapshot (the "vanishing
      // upload" / "empty VO1" bug).
      const lastLocalEdit = _localEditAt[row.wo];
      if(lastLocalEdit && row.updated_at && new Date(row.updated_at).getTime() < lastLocalEdit) return;
      const existing = DB.jobs[row.wo];
      if(existing && existing._updatedAt && row.updated_at && new Date(row.updated_at) < new Date(existing._updatedAt)){
        // This update is older than what we already have locally (arrived out of
        // order over the network) — ignore it so it can't overwrite newer data.
        return;
      }
      const j = (row.data && typeof row.data==='object') ? row.data : {};
      j.wo=row.wo; j.cust=row.cust; j.loc=row.loc; j.phase=row.phase; j.stage=row.stage; j.claimRef=row.claim_ref||j.claimRef||'';
      j._updatedAt = row.updated_at;
      preserveVOData(DB.jobs[row.wo], j);
      hydrateJob(j);
      DB.jobs[row.wo] = j;
      refreshAll();
    })
    .subscribe();
}

