function viewFinanceDoc(wo,docType){
  openDocForAction(wo,docType);
}
function openDocForAction(wo,docType){
  const job=wo?DB.jobs[wo]:null;
  const titles={vo1:'Works Valuation (VO1)'+(wo?' · WO '+wo:''),vo2:'Variation Order (VO2)'+(wo?' · WO '+wo:''),works_valuation:'Works Valuation Document'+(wo?' · WO '+wo:''),field_report:'Linesman Field Findings'+(wo?' · WO '+wo:''),works_instruction:'Works Instruction'+(wo?' · WO '+wo:''),gis_report:'GIS Map'+(wo?' · WO '+wo:''),bpc_wo:'BPC Work Order'+(wo?' · WO '+wo:''),annexure:'Annexure to Payment Certificate'+(wo?' · WO '+wo:''),payment_cert:'Payment Certificate'+(wo?' · WO '+wo:''),invoice:'Tax Invoice'+(wo?' · WO '+wo:''),list_of_jobs:'List of Jobs Done — Trends Engineering Services',bpc_spreadsheet:'BPC Spreadsheet — Batch Claim Document'};
  document.getElementById('docModalTitle').textContent=titles[docType]||docType;

  // For claim docs, try to find the Finance-saved version first
  const claimDocTypes=['annexure','payment_cert','invoice','list_of_jobs','bpc_spreadsheet'];
  let html='';

  if(claimDocTypes.includes(docType)){
    // Always regenerate live from the job's current VO1/VO2 data first. A saved
    // snapshot can go stale — e.g. if VO2 was entered or finished syncing after
    // the documents were first generated — and showing it would silently
    // display an outdated total, which is exactly what was happening before.
    if(job&&job.vo1&&job.vo1.items){
      html=buildDoc(docType,job);
    } else {
      // Search ALL jobs for any with same claimRef that has this doc saved
      const certNo=job?.claimRef;
      let found=false;
      if(certNo){
        const batchMatch=Object.values(DB.jobs).find(j=>j.claimRef===certNo&&j.savedDocs&&j.savedDocs[docType]&&j.savedDocs[docType].html);
        if(batchMatch){html=batchMatch.savedDocs[docType].html;found=true;}
      }
      // Also check DB.batchDocs
      if(!found&&certNo&&DB.batchDocs&&DB.batchDocs[certNo]){
        const bmap={annexure:'annexure',payment_cert:'paymentCert',invoice:'invoice',list_of_jobs:'listOfJobs',bpc_spreadsheet:'bpcSpreadsheet'};
        const bkey=bmap[docType];
        if(bkey&&DB.batchDocs[certNo][bkey]){html=DB.batchDocs[certNo][bkey];found=true;}
      }
      // Last resort: fall back to a saved snapshot on this job itself
      if(!found&&job&&job.savedDocs&&job.savedDocs[docType]&&job.savedDocs[docType].html){
        html=job.savedDocs[docType].html;
        found=true;
      }
      if(!found){
        html=buildDoc(docType,job);
      }
    }
  } else {
    // For non-claim docs, check savedDocs first then rebuild
    if(job&&job.savedDocs&&job.savedDocs[docType]&&job.savedDocs[docType].html){
      html=job.savedDocs[docType].html;
    } else {
      html=buildDoc(docType,job);
    }
  }

  document.getElementById('docModalBody').innerHTML=html;
  document.getElementById('docModalFoot').innerHTML=buildDocFoot(docType,job);
  openModal('docModal');
}
function buildDocFoot(docType,job){
  const wo=job?job.wo:'';
  const isMDView=CU==='md';
  // Print button — opens same clean popup
  let btns=`<button class="btn btn-print btn-sm" onclick="downloadDocAsPDF('${wo}','${docType}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>Print / PDF</button>`;

  if(wo){
    if(job&&job.scans&&job.scans[docType]){
      btns+=`<button class="btn btn-gn btn-sm" onclick="downloadScan('${wo}','${docType}')">&#11015; Signed Copy</button>`;
    }
    if(!isMDView){
      btns+=`<button class="btn btn-gn btn-sm" onclick="saveDocToStep('${wo}','${docType}')">&#128190; Save &amp; Attach</button>`;
      btns+=`<label class="scan-upload-label">📎 Upload / Replace<input type="file" id="scan-input-modal-${wo}-${docType}" accept="image/*,application/pdf" onchange="handleScan('${wo}','${docType}',this);closeModal('docModal')" style="display:none"></label>`;
    }
  }

  if(!isMDView&&CU==='admin'&&job){
    if(docType==='vo1'&&job.stage==='wo_received')
      btns+=`<button class="btn btn-am" onclick="advanceStage('${wo}','vo1_created')">✓ Mark VO1 Complete</button>`;
    if(docType==='vo2'&&(job.stage==='field_received'||job.stage==='vo2_created'))
      btns+=`<button class="btn btn-am" onclick="saveVO2('${wo}')">✓ Save VO2</button>`;
    if(docType==='works_instruction'&&(job.stage==='vo2_created'||job.stage==='work_instruction_ready'))
      btns+=`<button class="btn btn-am" onclick="advanceStageWI('${wo}')">✓ Works Instruction Ready</button>`;
    if(docType==='gis_report'&&job.stage==='gis_notified')
      btns+=`<button class="btn btn-am" onclick="checkGISComplete('${job.wo}')">✓ Mark GIS Complete</button>`;
    if(docType==='gis_cert'&&job.stage==='gis_notified')
      btns+=`<button class="btn btn-am" onclick="checkGISComplete('${job.wo}')">✓ Mark GIS Complete</button>`;
  }
  if(!isMDView&&CU==='finance'&&job){
    if(docType==='payment_cert'||docType==='invoice'||docType==='annexure'||docType==='list_of_jobs'||docType==='bpc_spreadsheet')
      btns+=`<button class="btn btn-gn btn-sm" onclick="saveDocToStep('${wo}','${docType}')">&#128190; Save &amp; Attach</button>`;
  }
  return btns;
}
/* ═══════════════════════════════════════
   EXTERNAL ROLE UPLOADS (Linesman, GIS, Teams)
═══════════════════════════════════════ */

/**
 * Handle external role uploads (Linesman findings, GIS reports, etc.)
 * Opens file browser, accepts multiple files, saves directly without modal form
 * externalRole: 'linesman_findings' | 'gis_report' | 'teams_photo'
 */
function openExternalUpload(wo, externalRole) {
  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.multiple = true;  // Allow multiple files
  fileInput.accept = 'image/*,application/pdf,.doc,.docx';
  
  fileInput.onchange = (e) => handleExternalUpload(wo, externalRole, e.target.files);
  fileInput.click();
}

/**
 * Process external role uploads
 * Saves files to BOTH stage arrays AND Documents section (savedDocs) for sync
 * Does NOT auto-advance stage for GIS - user must manually "Mark GIS Complete"
 */
/**
 * Process external role uploads (GIS and Linesman)
 * CRITICAL FIX: Use scans[key] pattern like Linesman docs to preserve original file format
 * For GIS: Store as scans['gis_report'] and scans['gis_cert']
 * This ensures files download as-is without any conversion
 */
async function handleExternalUpload(wo, externalRole, files) {
  if (!files || files.length === 0) return;

  const job = DB.jobs[wo];
  if (!job) return;

  // Initialize scans storage if needed
  if (!job.scans) job.scans = {};

  // Map external role to scans key (same pattern as Linesman)
  const scanKeyMap = {
    gis_report: 'gis_report',
    gis_certificate: 'gis_cert'
  };

  const scanKey = scanKeyMap[externalRole];
  if (!scanKey) return;

  const uploadedFiles = [];

  try {
    // Process files one at a time (not in parallel) so multiple files can't
    // race each other and clobber job.scans[scanKey] out of order.
    for (const file of Array.from(files)) {
      if (SB.enabled) {
        // PERFORMANCE / RELIABILITY FIX: upload straight to Supabase Storage
        // instead of embedding as base64 in the job record — see
        // uploadLinesmanScan for the full explanation of why this matters.
        const ext = (file.name.split('.').pop() || 'pdf').toLowerCase();
        const path = `${wo}/${scanKey}_${Date.now()}.${ext}`;
        const {error:upErr} = await SB.client.storage.from(SB.bucket).upload(path, file, {upsert:true, contentType:file.type||undefined});
        if (upErr) throw upErr;
        const url = SB.client.storage.from(SB.bucket).getPublicUrl(path).data.publicUrl;
        job.scans[scanKey] = {storagePath:path, url, filename:file.name, uploadedAt:new Date().toISOString(), role:CU};
        await SB.client.from('documents').insert({
          wo, doc_type:scanKey, is_signed:true, storage_path:path, filename:file.name, uploaded_role:CU,
        });
      } else {
        // Offline mode (no Supabase configured) — fall back to base64, same as before.
        const dataUrl = await new Promise((resolve,reject)=>{
          const reader = new FileReader();
          reader.onload = ev => resolve(ev.target.result);
          reader.onerror = () => reject(new Error('File read failed'));
          reader.readAsDataURL(file);
        });
        job.scans[scanKey] = {dataUrl, filename:file.name, uploadedAt:new Date().toISOString(), role:CU};
      }
      uploadedFiles.push(file.name);
    }

    addLog(wo, `GIS ${externalRole === 'gis_report' ? 'report' : 'certificate'} uploaded: ${uploadedFiles.join(', ')}`);
    toast(`✅ ${uploadedFiles.length} file(s) uploaded: ${uploadedFiles.join(', ')}`);

    markJobDirty(wo);
    await saveDBAndWait();
    const ov = document.getElementById('loadOverlay');
    if (ov) ov.style.display = 'flex';
    refreshDetail();
    refreshAll();
    if (ov) ov.style.display = 'none';
  } catch (err) {
    console.error('GIS upload error:', err);
    toast('Upload failed: ' + (err.message || 'check connection'), 'rd');
  }
}

/**
 * Manually mark GIS as complete after uploads are done
 * Only requires GIS reports to be uploaded, certificate is optional
 */
async function markGISComplete(wo) {
  const job = DB.jobs[wo];
  if (!job) return;
  
  // Only require GIS reports, not certificate
  if (!job.scans || !job.scans['gis_report']) {
    toast('Upload at least one GIS report first', 'am');
    return;
  }
  if (!job.scans || !job.scans['gis_cert']) {
    toast('Upload at least one GIS certificate first', 'am');
    return;
  }
  
  // Advance to gis_complete stage
  job.stage = 'gis_complete';
  job.actions['gis_complete'] = { date: new Date().toISOString().slice(0, 10), notes: '', extra: '' };
  addLog(wo, 'GIS documents complete — ready for claim batch');
  notify(['finance', 'md'], `GIS documents complete for WO ${wo} — ${job.cust}. Ready for claim batch.`, wo);
  
  // Auto-save GIS report document for MD to see
  if (!job.savedDocs) job.savedDocs = {};
  job.savedDocs['gis_report'] = {
    html: 'GIS report uploaded',
    savedAt: new Date().toISOString(),
    role: CU,
    autoSaved: true
  };
  
  markJobDirty(wo);
  await saveDBAndWait();
  refreshDetail();
  refreshAll();
  
  toast('✅ GIS marked as complete. Work order ready for Finance to generate claims.');
}

/**
 * Download external role uploaded file
 */
// DEPRECATED - GIS files now use scans[key] pattern like Linesman documents
// Keeping for backward compatibility with old data
function downloadExternalFile(wo, externalRole, fileIndex) {
  const job = DB.jobs[wo];
  if (!job) return;
  
  const roleFieldMap = {
    linesman_findings: 'linesmanDocs',
    gis_report: 'gisDocs',
    gis_certificate: 'gisCerts',
    teams_photo: 'teamPhotos'
  };
  const field = roleFieldMap[externalRole];
  if (!field || !job[field] || !job[field][fileIndex]) return;
  
  const file = job[field][fileIndex];
  const link = document.createElement('a');
  link.href = file.data;
  link.download = file.name;
  link.click();
}

/**
 * Delete external role uploaded file
 * CRITICAL FIX: For GIS, now uses scans[key] pattern
 */
function deleteExternalFile(wo, externalRole, fileIndex) {
  const job = DB.jobs[wo];
  if (!job) return;
  
  // Map to scans key for GIS documents
  const scansKeyMap = {
    gis_report: 'gis_report',
    gis_certificate: 'gis_cert'
  };
  
  const scanKey = scansKeyMap[externalRole];
  if (scanKey) {
    // New pattern: GIS files use scans[key]
    if (confirm('Delete this file?')) {
      delete job.scans[scanKey];
      markJobDirty(wo);
      saveDB();
      refreshDetail();
      toast('File deleted');
    }
    return;
  }
  
  // Legacy pattern for old data
  const roleFieldMap = {
    linesman_findings: 'linesmanDocs',
    teams_photo: 'teamPhotos'
  };
  const field = roleFieldMap[externalRole];
  if (!field || !job[field]) return;
  
  if (confirm('Delete this file?')) {
    job[field].splice(fileIndex, 1);
    saveDB();
    refreshDetail();
    toast('File deleted');
  }
}

/**
 * Show list of uploaded external files
 * CRITICAL FIX: GIS documents now use scans[key] pattern for proper file preservation
 */
function showExternalFiles(wo, externalRole) {
  const job = DB.jobs[wo];
  if (!job) return '';
  
  // Map to scans key for GIS documents
  const scansKeyMap = {
    gis_report: 'gis_report',
    gis_certificate: 'gis_cert'
  };
  
  const scanKey = scansKeyMap[externalRole];
  if (scanKey) {
    // NEW PATTERN: GIS files use scans[key] to preserve original format
    const scan = job.scans?.[scanKey];
    if (!scan) {
      return '<div style="padding:1rem;color:var(--tx3);font-size:.8rem">No files uploaded yet</div>';
    }
    
    return `
      <div style="display:flex;gap:10px;padding:.75rem;background:var(--sf2);border-radius:var(--rs);align-items:center;margin-bottom:.5rem">
        <span style="flex:1">
          <div style="font-weight:600;font-size:.9rem">${scan.filename}</div>
          <div style="font-size:.75rem;color:var(--tx3)">
            ${scan.uploadedAt ? new Date(scan.uploadedAt).toLocaleDateString() : 'Unknown date'}
          </div>
        </span>
        <button class="btn btn-gn btn-sm" onclick="downloadScan('${wo}','${scanKey}')">⬇ Download</button>
        <button class="btn btn-rd btn-sm" onclick="deleteExternalFile('${wo}','${externalRole}',0)">✕ Delete</button>
      </div>
    `;
  }
  
  // Legacy pattern for old data structures
  const roleFieldMap = {
    linesman_findings: 'linesmanDocs',
    teams_photo: 'teamPhotos'
  };
  const field = roleFieldMap[externalRole];
  const files = job[field] || [];
  
  if (!files.length) {
    return '<div style="padding:1rem;color:var(--tx3);font-size:.8rem">No files uploaded yet</div>';
  }
  
  return files.map((f, idx) => `
    <div style="display:flex;gap:10px;padding:.75rem;background:var(--sf2);border-radius:var(--rs);align-items:center;margin-bottom:.5rem">
      <span style="flex:1">
        <div style="font-weight:600;font-size:.9rem">${f.name}</div>
        <div style="font-size:.75rem;color:var(--tx3)">
          ${(f.size / 1024).toFixed(1)} KB · ${new Date(f.uploadedAt).toLocaleDateString()}
        </div>
      </span>
      <button class="btn btn-gn btn-sm" onclick="downloadExternalFile('${wo}','${externalRole}',${idx})">⬇ Download</button>
      <button class="btn btn-rd btn-sm" onclick="deleteExternalFile('${wo}','${externalRole}',${idx})">✕ Delete</button>
    </div>
  `).join('');
}

/**
 * Notify external role (Linesman or GIS) - no form, just mark as notified
 */
async function notifyExternalRole(wo, role) {
  const job = DB.jobs[wo];
  if (!job) return;
  
  if (role === 'linesman') {
    job.stage = 'linesman_notified';
    job.actions['linesman_notified'] = { date: new Date().toISOString().slice(0,10), notes: '', extra: '' };
    addLog(wo, 'Linesman notified — awaiting field documents');
    
    // CREATE NOTIFICATION FOR LINESMAN
    notify('linesman', `📋 WO ${wo} (${job.cust}): Please upload the 6 required field documents.`, wo);
    
    // NOTIFY ADMIN
    notify(['md'], `Linesman notified for WO ${wo} — ${job.cust}. Awaiting field documents.`, wo);
    toast('✅ Linesman notified. They will upload documents from their dashboard.');
  } else if (role === 'gis') {
    job.stage = 'gis_notified';
    job.actions['gis_notified'] = { date: new Date().toISOString().slice(0,10), notes: '', extra: '' };
    addLog(wo, 'GIS consultant notified externally — awaiting GIS report');
    notify(['md'], `GIS consultant notified for WO ${wo} — ${job.cust}. Awaiting GIS report.`, wo);
    toast('✅ GIS consultant notified. Now upload their report when ready.');
  }
  
  markJobDirty(wo);
  await saveDBAndWait();
  refreshDetail();
  refreshAll();
}

